 *
 * Within an observation window, opposite pair events on the same target
 * cancel: for an 'add' group a remove clears the target and vice versa,
 * and add/remove events cancel pending 'change' state.
 */
function updatePairGroupState(
    group: TrackingGroup,
    eid: number,
    relation: Relation,
    target: Entity,
    eventType: EventType
): void {
    let op: 'set' | 'clear' | 'noop';
    if (group.type === eventType) op = 'set';
    else if (eventType === 'change') op = 'noop';
    else op = 'clear';
    if (op === 'noop') return;

    const pairs = group.pairs!;
    const pairState = group.pairState!;

    if (op === 'set') {
        let state = pairState.get(eid);
        if (!state) {
            state = [];
            pairState.set(eid, state);
        }
        for (let i = 0; i < pairs.length; i++) {
            if (pairs[i][$internal].relation !== relation) continue;
            let targets = state[i];
            if (!targets) {
                targets = new Set<number>();
                state[i] = targets;
            }
            targets.add(target);
        }
        return;
    }

    const state = pairState.get(eid);
    if (!state) return;
    for (let i = 0; i < pairs.length; i++) {
        if (pairs[i][$internal].relation !== relation) continue;
        state[i]?.delete(target);
    }
}

/**
 * Check whether a pair group is satisfied for an entity based on the
 * current window's pair tracker state.
 */
export function evaluatePairGroup(group: TrackingGroup, eid: number): boolean {
    const pairs = group.pairs!;
    const state = group.pairState?.get(eid);
    const logic = group.logic;

    for (let i = 0; i < pairs.length; i++) {
        const target = pairs[i][$internal].target;
        const targets = state?.[i];
        const slot = target === '*' ? !!targets && targets.size > 0 : !!targets && targets.has(target);
        if (logic === 'and') {
            if (!slot) return false;
        } else if (slot) {
            return true;
        }
    }
    return logic === 'and';
}

/**
 * Backfill check for pair groups when a query instance is created:
 * evaluate the pair group against the world's pair snapshot/dirty/changed
 * maps for the group's tracking ID.
 */
export function checkPairGroupInitial(world: World, group: TrackingGroup, entity: Entity): boolean {
    const ctx = world[$internal];
    const pairs = group.pairs!;
    const id = group.id;
    const snapshot = ctx.pairSnapshots.get(id);
    const dirty = ctx.pairDirty.get(id);
    const changed = ctx.pairChanged.get(id);
    const eid = getEntityId(entity);
    const logic = group.logic;

    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];
        const pairCtx = pair[$internal];
        const relation = pairCtx.relation as Relation<Trait>;
        const target = pairCtx.target;
        const relationTraitId = relation[$internal].trait.id;

        const snapTargets = snapshot?.get(relationTraitId)?.get(eid);
        const dirtyTargets = dirty?.get(relationTraitId)?.get(eid);
        const changedTargets = changed?.get(relationTraitId)?.get(eid);

        let slot: boolean;
        if (target === '*') {
            slot = checkWildcardPairSlot(
                world,
                group.type,
                relation,
                entity,
                snapTargets,
                dirtyTargets,
                changedTargets
            );
        } else {
            slot = checkSpecificPairSlot(
                world,
                group.type,
                relation,
                entity,
                target,
                snapTargets,
                dirtyTargets,
                changedTargets
            );
        }

        if (logic === 'and') {
            if (!slot) return false;
        } else if (slot) {
            return true;
        }
    }
    return logic === 'and';
}

function checkSpecificPairSlot(
    world: World,
    type: EventType,
    relation: Relation<Trait>,
    entity: Entity,
    target: Entity,
    snapTargets: Set<number> | undefined,
    dirtyTargets: Set<number> | undefined,
    changedTargets: Set<number> | undefined
): boolean {
    const current = hasRelationToTarget(world, relation, entity, target);
    const old = snapTargets?.has(target) ?? false;

    if (type === 'add') return current && !old;
    if (type === 'remove') {
        if (old && !current) return true;
        // Added and removed within the window (or since the snapshot).
        return !old && !current && (dirtyTargets?.has(target) ?? false);
    }
    // change
    return current && (changedTargets?.has(target) ?? false);
}

function checkWildcardPairSlot(
    world: World,
    type: EventType,
    relation: Relation<Trait>,
    entity: Entity,
    snapTargets: Set<number> | undefined,
    dirtyTargets: Set<number> | undefined,
    changedTargets: Set<number> | undefined
): boolean {
    const currentTargets = getRelationTargets(world, relation, entity);
    const currentSet = new Set<number>(currentTargets);

    // Union of all targets that could produce a match.
    const candidates = new Set<number>(currentSet);
    snapTargets?.forEach((t) => candidates.add(t));
    dirtyTargets?.forEach((t) => candidates.add(t));
    if (type === 'change') changedTargets?.forEach((t) => candidates.add(t));

    for (const t of candidates) {
        const current = currentSet.has(t);
        const old = snapTargets?.has(t) ?? false;
        const dirty = dirtyTargets?.has(t) ?? false;
        const changed = changedTargets?.has(t) ?? false;

        let slot = false;
        if (type === 'add') slot = current && !old;
        else if (type === 'remove') slot = (old && !current) || (!old && !current && dirty);
        else slot = current && changed;

        if (slot) return true;
    }
    return false;
}
