{"command": "cd /app && cat > packages/core/src/query/query-result.ts <<'EOF'
import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import {
    getFirstRelationTarget,
    getRelationData,
    hasRelationPair,
    setRelationData,
} from '../relation/relation';
import type { Relation, RelationPair } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged, setPairChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];
    // Parallel to traits: the relation pair to resolve per-target data for,
    // when the trait comes from a pair (pair parameter or pair tracking modifier).
    const pairTargets: (RelationPair | undefined)[] = [];

    getQueryStores(params, traits, stores, pairTargets, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: traits.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(world, entity, eid, traits, stores, pairTargets, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: traits.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait, RelationPair | undefined][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                getTrackedTraits(traits, world, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(world, entity, eid, traits, stores, pairTargets, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked traits.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        const index = trackedIndices[j];
                        commitStateValue(
                            world,
                            entity,
                            traits[index],
                            stores[index],
                            pairTargets[index],
                            state[index],
                            atomicSnapshots[index],
                            changedPairs
                        );
                    }

                    // Commit all changes back to the stores for untracked traits.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        const index = untrackedIndices[j];
                        commitStateValue(
                            world,
                            entity,
                            traits[index],
                            stores[index],
                            pairTargets[index],
                            state[index],
                            null,
                            null
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                triggerChangeEvents(world, changedPairs);
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait, RelationPair | undefined][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(world, entity, eid, traits, stores, pairTargets, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        commitStateValue(
                            world,
                            entity,
                            traits[j],
                            stores[j],
                            pairTargets[j],
                            state[j],
                            atomicSnapshots[j],
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                triggerChangeEvents(world, changedPairs);
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(world, entity, eid, traits, stores, pairTargets, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        commitStateValue(
                            world,
                            entity,
                            traits[j],
                            stores[j],
                            pairTargets[j],
                            state[j],
                            null,
                            null
                        );
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            traits.length = 0;
            stores.length = 0;
            pairTargets.length = 0;
            getQueryStores(params, traits, stores, pairTargets, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getTrackedTraits(
    traits: Trait[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/**
 * Resolve the target for a pair that may use the '*' wildcard (first target).
 */
function resolvePairTarget(
    world: World,
    entity: Entity,
    pair: RelationPair
): Entity | undefined {
    const pairCtx = pair[$internal];
    const relation = pairCtx.relation as Relation<Trait>;
    const target = pairCtx.target;
    if (typeof target === 'number') return target;
    return getFirstRelationTarget(world, relation, entity);
}

/**
 * Read per-target relation data for a pair.
 */
function getRelationDataForPair(
    world: World,
    entity: Entity,
    pair: RelationPair
): unknown {
    const pairCtx = pair[$internal];
    const relation = pairCtx.relation as Relation<Trait>;
    const target = pairCtx.target;

    if (typeof target === 'number') {
        if (!hasRelationPair(world, entity, pair)) return undefined;
        return getRelationData(world, entity, relation, target);
    }

    // Wildcard: resolve the first target.
    const first = getFirstRelationTarget(world, relation, entity);
    if (first === undefined) return undefined;
    return getRelationData(world, entity, relation, first);
}

/* @inline */ function createSnapshots(
    world: World,
    entity: Entity,
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    pairTargets: (RelationPair | undefined)[],
    state: any[]
) {
    for (let i = 0; i < traits.length; i++) {
        const pair = pairTargets[i];
        if (pair) {
            state[i] = getRelationDataForPair(world, entity, pair);
            continue;
        }
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    world: World,
    entity: Entity,
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    pairTargets: (RelationPair | undefined)[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        const pair = pairTargets[j];
        if (pair) {
            const value = getRelationDataForPair(world, entity, pair);
            state[j] = value;
            // Relation data is reconstructed per read, so the value itself is
            // a snapshot for change detection.
            atomicSnapshots[j] = value;
            continue;
        }
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        state[j] = value;
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }
}

/**
 * Commit a state value back to its store.
 *
 * Pair-resolved traits write to the specific target's slot and detect
 * changes via shallow comparison. Regular traits use the fast store setters.
 */
function commitStateValue(
    world: World,
    entity: Entity,
    trait: Trait,
    store: Store<any>,
    pair: RelationPair | undefined,
    value: any,
    snapshot: any,
    changedPairs: [Entity, Trait, RelationPair | undefined][] | null
) {
    if (pair) {
        const target = resolvePairTarget(world, entity, pair);
        if (target !== undefined && value !== undefined) {
            setRelationData(world, entity, pair[$internal].relation as Relation<Trait>, target, value);
        }
        if (changedPairs && snapshot !== null && !shallowEqual(value, snapshot)) {
            changedPairs.push([entity, trait, pair]);
        }
        return;
    }

    const eid = getEntityId(entity);
    const ctx = trait[$internal];

    if (changedPairs) {
        let changed = false;
        if (ctx.type === 'aos') {
            changed = ctx.fastSetWithChangeDetection(eid, store, value);
            if (!changed && snapshot !== null) {
                changed = !shallowEqual(value, snapshot);
            }
        } else {
            changed = ctx.fastSetWithChangeDetection(eid, store, value);
        }
        if (changed) changedPairs.push([entity, trait, undefined]);
    } else {
        ctx.fastSet(eid, store, value);
    }
}

/**
 * Trigger change events for committed state changes.
 */
function triggerChangeEvents(
    world: World,
    changedPairs: [Entity, Trait, RelationPair | undefined][]
) {
    for (let i = 0; i < changedPairs.length; i++) {
        const [entity, trait, pair] = changedPairs[i];
        if (pair) {
            setPairChanged(world, entity, trait, pair[$internal].target);
        } else {
            setChanged(world, entity, trait);
        }
    }
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    pairTargets: (RelationPair | undefined)[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                pairTargets.push(param);
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            const pairs = param.pairs;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                traits.push(trait);
                stores.push(getStore(world, trait));
                pairTargets.push(pairs ? findPairForTrait(pairs, trait) : undefined);
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            traits.push(trait);
            stores.push(getStore(world, trait));
            pairTargets.push(undefined);
        }
    }
}

/**
 * Find the pair in a modifier's tracked pairs that resolves to the given
 * base trait. A specific target pair takes precedence over the wildcard.
 */
function findPairForTrait(pairs: RelationPair[], trait: Trait): RelationPair | undefined {
    let wildcard: RelationPair | undefined;
    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];
        const base = pair[$internal].relation[$internal].trait;
        if (base !== trait) continue;
        const target = pair[$internal].target;
        if (typeof target === 'number') return pair;
        wildcard = pair;
    }
    return wildcard;
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
