import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { hasRelationPair } from '../relation/relation';
import type { Relation } from '../relation/types';
import { isRelationPair } from '../relation/utils/is-relation';
import { registerTrait, trait } from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { TagTrait, Trait } from '../trait/types';
import { universe } from '../universe/universe';
import { SparseSet } from '../utils/sparse-set';
import type { World } from '../world';
import { getTrackingType, isModifier, isOrWithModifiers, isTrackingModifier } from './modifier';
import { createQueryResult } from './query-result';
import { $queryRef } from './symbols';
import {
    type EventType,
    type Modifier,
    type Query,
    type QueryInstance,
    type QueryParameter,
    type QueryResult,
    type QuerySubscriber,
    type TrackingGroup,
} from './types';
import { checkPairGroupInitial } from './utils/apply-pair-event';
import { checkQuery } from './utils/check-query';
import { checkQueryTracking } from './utils/check-query-tracking';
import { checkQueryWithRelations } from './utils/check-query-with-relations';
import { createQueryHash } from './utils/create-query-hash';

export const IsExcluded: TagTrait = trait();

export function runQuery<T extends QueryParameter[]>(
    world: World,
    query: QueryInstance<T>,
    params: QueryParameter[]
): QueryResult<T> {
    commitQueryRemovals(world);

    // With hybrid bitmask strategy, query.entities is already incrementally maintained
    // with both trait and relation filters applied. Just return the pre-filtered entities.
    const entities = query.entities.dense.slice() as Entity[];

    // Clear so it can accumulate again.
    if (query.isTracking) {
        query.entities.clear();
        // PERF: Use indexed loop instead of for...of
        const len = entities.length;
        for (let i = 0; i < len; i++) {
            query.resetTrackingBitmasks(entities[i]);
        }
        // Clear pair-level tracker state so events accumulate again.
        const groups = query.trackingGroups;
        for (let i = 0; i < groups.length; i++) {
            const pairState = groups[i].pairState;
            if (pairState) pairState.clear();
        }
    }

    return createQueryResult(world, entities, query, params);
}

export function addEntityToQuery(query: QueryInstance, entity: Entity) {
    query.toRemove.remove(entity);
    query.entities.add(entity);

    // Notify subscriptions.
    for (const sub of query.addSubscriptions) {
        sub(entity);
    }

    query.version++;
}

export function removeEntityFromQuery(world: World, query: QueryInstance, entity: Entity) {
    if (!query.entities.has(entity) || query.toRemove.has(entity)) return;

    const ctx = world[$internal];

    query.toRemove.add(entity);
    ctx.dirtyQueries.add(query);

    // Notify subscriptions.
    for (const sub of query.removeSubscriptions) {
        sub(entity);
    }

    query.version++;
}

export function commitQueryRemovals(world: World) {
    const ctx = world[$internal];
    if (!ctx.dirtyQueries.size) return;

    for (const query of ctx.dirtyQueries) {
        for (let i = query.toRemove.dense.length - 1; i >= 0; i--) {
            const eid = query.toRemove.dense[i];
            query.toRemove.remove(eid);
            query.entities.remove(eid);
        }
    }

    ctx.dirtyQueries.clear();
}

/** Reset tracking state for an entity across all tracking groups */
export function resetQueryTrackingBitmasks(query: QueryInstance, eid: number) {
    const groups = query.trackingGroups;
    const len = groups.length;
    for (let i = 0; i < len; i++) {
        const trackers = groups[i].trackers;
        const trackersLen = trackers.length;
        for (let j = 0; j < trackersLen; j++) {
            const tracker = trackers[j];
            if (tracker) tracker[eid] = 0;
        }
    }
}

import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { getRelationTargets, hasRelationToTarget } from '../../relation/relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import type { World } from '../../world';
import type { EventType, QueryInstance, TrackingGroup } from '../types';
import { checkQueryTracking } from './check-query-tracking';

/**
 * Apply a pair-level tracking event (add/remove/change of a specific
 * relation target) to a query: update the pair group tracker state and
 * re-evaluate the full query for the entity.
 */
export function applyPairEvent(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    relation: Relation,
    target: Entity
): void {
    // Fast path: the query has no pair-level groups.
    const groups = query.trackingGroups;
    let hasPairGroup = false;
    for (let i = 0; i < groups.length; i++) {
        if (groups[i].pairs) {
            hasPairGroup = true;
            break;
        }
    }
    if (!hasPairGroup) return;

    const eid = getEntityId(entity);

    // Update pair group tracker state for groups that track this relation.
    for (let i = 0; i < groups.length; i++) {
        const group = groups[i];
        if (!group.pairs) continue;
        let tracksRelation = false;
        for (const pair of group.pairs) {
            if (pair[$internal].relation === relation) {
                tracksRelation = true;
                break;
            }
        }
        if (!tracksRelation) continue;
        if (!group.pairState) group.pairState = new Map();
        updatePairGroupState(group, eid, relation, target, eventType);
    }

    if (process.env.DEBUG_PAIR) {
        const st = groups.find((g) => g.pairs)?.pairState?.get(eid);
        console.error(
            `[pair-event] type=${eventType} rel=${relation[$internal].trait.id} target=${getEntityId(target)} ` +
            `state=${JSON.stringify(st ? st.map((x) => [...(x ?? [])].map(getEntityId)) : null)}`
        );
    }

    // Re-evaluate the full query (static constraints + trait groups + pair groups).
    // Pair 'change' events still count as a change for the base trait, so the
    // event carries the base trait generation/bitflag for trait group trackers.
    const instance = world[$internal].traitInstances[relation[$internal].trait.id];
    const generationId = instance ? instance.generationId : 0;
    const bitflag = instance ? instance.bitflag : 0;
    const match = checkQueryTracking(world, query, entity, eventType, generationId, bitflag, {
        relation,
        target,
    });
    if (process.env.DEBUG_PAIR) {
        console.error(`[pair-event] -> match=${match} inQuery=${query.entities.has(entity)}`);
    }
    if (match) query.add(entity);
    else query.remove(world, entity);
}

/**
 * Update a pair group's per-entity tracker state for a pair event.
 *
 * Within an observation window, opposite pair events on the same target
 * cancel: for an 'add' group a remove clears the target and vice versa,
 * and add/remove events cancel pending 'change' state.
 */
function updatePairGroupState(
    group: TrackingGroup,
    eid: number,
    relation: Relation,
    target: Entity,
    eventType: EventType
): void {
    let op: 'set' | 'clear' | 'noop';
    if (group.type === eventType) op = 'set';
    else if (eventType === 'change') op = 'noop';
    else op = 'clear';
    if (op === 'noop') return;

    const pairs = group.pairs!;
    const pairState = group.pairState!;

    if (op === 'set') {
        let state = pairState.get(eid);
        if (!state) {
            state = [];
            pairState.set(eid, state);
        }
        for (let i = 0; i < pairs.length; i++) {
            if (pairs[i][$internal].relation !== relation) continue;
            let targets = state[i];
            if (!targets) {
                targets = new Set<number>();
                state[i] = targets;
            }
            targets.add(target);
        }
        return;
    }

    const state = pairState.get(eid);
    if (!state) return;
    for (let i = 0; i < pairs.length; i++) {
        if (pairs[i][$internal].relation !== relation) continue;
        state[i]?.delete(target);
    }
}

/**
 * Check whether a pair group is satisfied for an entity based on the
 * current window's pair tracker state.
 */
export function evaluatePairGroup(group: TrackingGroup, eid: number): boolean {
    const pairs = group.pairs!;
    const state = group.pairState?.get(eid);
    const logic = group.logic;

    for (let i = 0; i < pairs.length; i++) {
        const target = pairs[i][$internal].target;
        const targets = state?.[i];
        const slot = target === '*' ? !!targets && targets.size > 0 : !!targets && targets.has(target);
        if (logic === 'and') {
            if (!slot) return false;
        } else if (slot) {
            return true;
        }
    }
    return logic === 'and';
}

/**
 * Backfill check for pair groups when a query instance is created:
 * evaluate the pair group against the world's pair snapshot/dirty/changed
 * maps for the group's tracking ID.
 */
export function checkPairGroupInitial(world: World, group: TrackingGroup, entity: Entity): boolean {
    const ctx = world[$internal];
    const pairs = group.pairs!;
    const id = group.id;
    const snapshot = ctx.pairSnapshots.get(id);
    const dirty = ctx.pairDirty.get(id);
    const changed = ctx.pairChanged.get(id);
    const eid = getEntityId(entity);
    const logic = group.logic;

    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];
        const pairCtx = pair[$internal];
        const relation = pairCtx.relation as Relation<Trait>;
        const target = pairCtx.target;
        const relationTraitId = relation[$internal].trait.id;

        const snapTargets = snapshot?.get(relationTraitId)?.get(eid);
        const dirtyTargets = dirty?.get(relationTraitId)?.get(eid);
        const changedTargets = changed?.get(relationTraitId)?.get(eid);

        let slot: boolean;
        if (target === '*') {
            slot = checkWildcardPairSlot(
                world,
                group.type,
                relation,
                entity,
                snapTargets,
                dirtyTargets,
                changedTargets
            );
        } else {
            slot = checkSpecificPairSlot(
                world,
                group.type,
                relation,
                entity,
                target,
                snapTargets,
                dirtyTargets,
                changedTargets
            );
        }

        if (logic === 'and') {
            if (!slot) return false;
        } else if (slot) {
            return true;
        }
    }
    return logic === 'and';
}

function checkSpecificPairSlot(
    world: World,
    type: EventType,
    relation: Relation<Trait>,
    entity: Entity,
    target: Entity,
    snapTargets: Set<number> | undefined,
    dirtyTargets: Set<number> | undefined,
    changedTargets: Set<number> | undefined
): boolean {
    const current = hasRelationToTarget(world, relation, entity, target);
    const old = snapTargets?.has(target) ?? false;

    if (type === 'add') return current && !old;
    if (type === 'remove') {
        if (old && !current) return true;
        // Added and removed within the window (or since the snapshot).
        return !old && !current && (dirtyTargets?.has(target) ?? false);
    }
    // change
    return current && (changedTargets?.has(target) ?? false);
}

function checkWildcardPairSlot(
    world: World,
    type: EventType,
    relation: Relation<Trait>,
    entity: Entity,
    snapTargets: Set<number> | undefined,
    dirtyTargets: Set<number> | undefined,
    changedTargets: Set<number> | undefined
): boolean {
    const currentTargets = getRelationTargets(world, relation, entity);
    const currentSet = new Set<number>(currentTargets);

    // Union of all targets that could produce a match.
    const candidates = new Set<number>(currentSet);
    snapTargets?.forEach((t) => candidates.add(t));
    dirtyTargets?.forEach((t) => candidates.add(t));
    if (type === 'change') changedTargets?.forEach((t) => candidates.add(t));

    for (const t of candidates) {
        const current = currentSet.has(t);
        const old = snapTargets?.has(t) ?? false;
        const dirty = dirtyTargets?.has(t) ?? false;
        const changed = changedTargets?.has(t) ?? false;

        let slot = false;
        if (type === 'add') slot = current && !old;
        else if (type === 'remove') slot = (old && !current) || (!old && !current && dirty);
        else slot = current && changed;

        if (slot) return true;
    }
    return false;
}

