import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { PairTrackingMap } from '../../world/types';

// Some values are reserved.
// 0 - has
// 1 - not
// 2 - or
let cursor = 3;

export function createTrackingId() {
    return cursor++;
}

export function getTrackingCursor() {
    return cursor;
}

export function setTrackingMasks(world: World, id: number) {
    const ctx = world[$internal];
    const snapshot = structuredClone(ctx.entityMasks);
    ctx.trackingSnapshots.set(id, snapshot);

    // For dirty and changed masks, make clone of entity masks and set all bits to 0.
    ctx.dirtyMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );

    ctx.changedMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );

    // Snapshot the current relation pair ownership for pair-level tracking.
    ctx.pairSnapshots.set(id, createPairSnapshot(world));
    ctx.pairDirty.set(id, new Map());
    ctx.pairChanged.set(id, new Map());
}

/**
 * Capture the current relation pair ownership for all relation traits:
 * relation traitId -> entityId -> set of targets.
 */
export function createPairSnapshot(world: World): PairTrackingMap {
    const ctx = world[$internal];
    const snapshot: PairTrackingMap = new Map();

    const traitInstances = ctx.traitInstances;
    for (let traitId = 0; traitId < traitInstances.length; traitId++) {
        const instance = traitInstances[traitId];
        if (!instance || !instance.relationTargets) continue;
        if (!instance.trait[$internal].relation) continue;

        const targets = instance.relationTargets;
        const byEntity = new Map<number, Set<number>>();
        for (let eid = 0; eid < targets.length; eid++) {
            const target = targets[eid];
            if (!target) continue;
            const set = byEntity.get(eid) ?? new Set<number>();
            if (Array.isArray(target)) {
                for (const t of target) set.add(t);
            } else {
                set.add(target);
            }
            byEntity.set(eid, set);
        }
        snapshot.set(traitId, byEntity);
    }

    return snapshot;
}

/**
 * Record a pair (relation, target) as touched (dirty or changed) for a
 * tracking ID map.
 */
export function touchPairTracking(
    map: PairTrackingMap,
    relationTraitId: number,
    entity: Entity,
    target: Entity
): void {
    const eid = getEntityId(entity);
    let byEntity = map.get(relationTraitId);
    if (!byEntity) {
        byEntity = new Map<number, Set<number>>();
        map.set(relationTraitId, byEntity);
    }
    let targets = byEntity.get(eid);
    if (!targets) {
        targets = new Set<number>();
        byEntity.set(eid, targets);
    }
    targets.add(target);
}
