    world.query(Added(ChildOf(parent)));
    world.query(Removed(ChildOf(parent)));
    a.add(ChildOf(parent));
    a.remove(ChildOf(parent)); // add+remove same window
    check('add+remove cancels Added', world.query(Added(ChildOf(parent))).length === 0);
    check('add+remove cancels Removed', world.query(Removed(ChildOf(parent))).length === 0);
    a.remove(ChildOf(parent)); // remove (trait gone) then re-add
    a.add(ChildOf(parent));
    a.remove(ChildOf(parent));
    check('remove+remove+add+remove: Added empty', world.query(Added(ChildOf(parent))).length === 0);
    check('remove+remove+add+remove: Removed has a', ids(world.query(Removed(ChildOf(parent)))) === AID(a));
    world.destroy();
}

// 7. Destruction fires pair removal for all active pairs
{
    const world = createWorld();
    const ChildOf = relation();
    const Removed = createRemoved();
    const p1 = world.spawn();
    const p2 = world.spawn();
    const a = world.spawn();
    a.add(ChildOf(p1), ChildOf(p2));
    world.query(Removed(ChildOf(p1)));
    world.query(Removed(ChildOf(p2)));
    a.destroy();
    check('destroy -> Removed(p1)', ids(world.query(Removed(ChildOf(p1)))) === AID(a));
    check('destroy -> Removed(p2)', ids(world.query(Removed(ChildOf(p2)))) === AID(a));
    world.destroy();
}

// 8. Or composition
{
    const world = createWorld();
    const ChildOf = relation();
    const Added = createAdded();
    const p1 = world.spawn();
    const p2 = world.spawn();
    const a = world.spawn();
    const b = world.spawn();
    world.query(Or(Added(ChildOf(p1)), Added(ChildOf(p2))));
    a.add(ChildOf(p2));
    b.add(ChildOf(p1));
    check('Or: both targets fire', ids(world.query(Or(Added(ChildOf(p1)), Added(ChildOf(p2))))) === AID(a) + ',' + AID(b));
    world.destroy();
}

// 9. Different targets -> distinct cached queries
{
    const world = createWorld();
    const ChildOf = relation();
    const Added = createAdded();
    const p1 = world.spawn();
    const p2 = world.spawn();
    world.query(Added(ChildOf(p1)));
    world.query(Added(ChildOf(p2)));
    const size = (world as any)[$internal].queriesHashMap.size;
    check('distinct cached queries', size === 2, size);
    world.destroy();
}

// 10. Pair + trait param: all constraints together
{
    const world = createWorld();
    const ChildOf = relation();
    const Position = trait();
    const Added = createAdded();
    const parent = world.spawn();
    const a = world.spawn();
    const b = world.spawn();
    a.add(ChildOf(parent), Position);
    b.add(ChildOf(parent));
    check('backfill pair+trait', ids(world.query(Added(ChildOf(parent)), Position)) === AID(a));
    a.remove(Position);
    check('event pair+trait gate', world.query(Added(ChildOf(parent)), Position).length === 0);
    world.destroy();
}

// 11. entity.changed(RelationPair)
{
    const world = createWorld();
    const ChildOf = relation({ store: { x: 0 } });
    const Changed = createChanged();
    const parent = world.spawn();
    const a = world.spawn();
    const b = world.spawn();
    a.add(ChildOf(parent));
    world.query(Changed(ChildOf(parent)));
    check('precond empty', world.query(Changed(ChildOf(parent))).length === 0);
    b.changed(ChildOf(parent)); // no pair -> ignored
    check('changed ignored without pair', world.query(Changed(ChildOf(parent))).length === 0);
    a.changed(ChildOf(parent)); // manual pair-level change
    check('changed(pair) fires', ids(world.query(Changed(ChildOf(parent)))) === AID(a));
    world.query(Changed(ChildOf(parent)));
    a.set(ChildOf(parent), { x: 7 }); // data write -> pair change
    check('set(pair) fires', ids(world.query(Changed(ChildOf(parent)))) === AID(a));
    check('set data readable', a.get(ChildOf(parent))?.x === 7);
    world.destroy();
}

// 12. Per-target data resolution in query results
{
    const world = createWorld();
    const ChildOf = relation({ store: { x: 0 } });
    const Added = createAdded();
    const parent = world.spawn();
    const sib = world.spawn();
    const a = world.spawn();
    a.add(ChildOf(parent), ChildOf(sib));
    a.set(ChildOf(parent), { x: 11 });
    a.set(ChildOf(sib), { x: 22 });
    const q = world.query(ChildOf(sib), Added(ChildOf(sib)));
    let got: any;
    (q as any).readEach(([data]: any) => { got = data; });
    check('per-target readEach', got?.x === 22, got);
    world.destroy();
}

// 13. Factory long-lived across world reset
{
    const world = createWorld();
    world.init();
    const ChildOf = relation();
    const Added = createAdded();
    const Removed = createRemoved();
    const parent = world.spawn();
    const a = world.spawn();
    a.add(ChildOf(parent));
    world.query(Added(ChildOf(parent)));
    world.reset();
    const parent2 = world.spawn();
    const b = world.spawn();
    b.add(ChildOf(parent2));
    check('factory reuse after reset (Added)', ids(world.query(Added(ChildOf(parent2)))) === AID(b));
    b.remove(ChildOf(parent2));
    check('factory reuse after reset (Removed)', ids(world.query(Removed(ChildOf(parent2)))) === AID(b));
    world.destroy();
}

// 14. Backfill semantics (query created after events)
{
    const world = createWorld();
    const ChildOf = relation();
    const Added = createAdded();
    const Removed = createRemoved();
    const parent = world.spawn();
    const a = world.spawn();
    a.add(ChildOf(parent));
    check('backfill Added', ids(world.query(Added(ChildOf(parent)))) === AID(a));
    a.remove(ChildOf(parent));
    check('backfill: added+removed -> nothing', world.query(Added(ChildOf(parent))).length === 0 && world.query(Removed(ChildOf(parent))).length === 0);
    a.add(ChildOf(parent));
    a.remove(ChildOf(parent));
    check('backfill Removed (added+removed since snapshot)', ids(world.query(Removed(ChildOf(parent)))) === AID(a));
    world.destroy();
}

// 15. Wildcard changed
{
    const world = createWorld();
    const ChildOf = relation({ store: { x: 0 } });
    const Changed = createChanged();
    const parent = world.spawn();
    const a = world.spawn();
    a.add(ChildOf(parent));
    world.query(Changed(ChildOf('*')));
    a.set(ChildOf(parent), { x: 3 });
    check('wildcard changed fires', ids(world.query(Changed(ChildOf('*')))) === AID(a));
    world.destroy();
}

