+    it('should track Added for a specific relation pair', () => {
+        const ChildOf = relation();
+        const Added = createAdded();
+
+        const parent = world.spawn();
+        const other = world.spawn();
+        const entityA = world.spawn();
+
+        let entities = world.query(Added(ChildOf(parent)));
+        expect(entities.length).toBe(0);
+
+        entityA.add(ChildOf(parent));
+        entities = world.query(Added(ChildOf(parent)));
+        expect(entities[0]).toBe(entityA);
+
+        // Adding the relation to another target does not fire for this target.
+        world.query(Added(ChildOf(parent)));
+        entityA.add(ChildOf(other));
+        entities = world.query(Added(ChildOf(parent)));
+        expect(entities.length).toBe(0);
+    });
+
+    it('should track non-first pair additions at pair level', () => {
+        const ChildOf = relation();
+        const Added = createAdded();
+
+        const parent = world.spawn();
+        const sibling = world.spawn();
+        const entityA = world.spawn();
+
+        // The entity already has the relation to a different target.
+        entityA.add(ChildOf(parent));
+        expect(world.query(Added(ChildOf(sibling))).length).toBe(0);
+
+        entityA.add(ChildOf(sibling));
+        const entities = world.query(Added(ChildOf(sibling)));
+        expect(entities[0]).toBe(entityA);
+    });
+
+    it('should track Removed for a specific relation pair', () => {
+        const ChildOf = relation();
+        const Removed = createRemoved();
+
+        const parent = world.spawn();
+        const entityA = world.spawn();
+
+        entityA.add(ChildOf(parent));
+        expect(world.query(Removed(ChildOf(parent))).length).toBe(0);
+
+        entityA.remove(ChildOf(parent));
+        const entities = world.query(Removed(ChildOf(parent)));
+        expect(entities[0]).toBe(entityA);
+    });
